def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: Point
    :type value: Point
    :return: A serializable representation of the point (dict or tuple).
    """
    if value is None:
        return None

    # If the point is a namedtuple or has a _asdict() method
    if hasattr(value, "_asdict"):
        return value._asdict()

    # If the point has explicit x and y attributes
    if hasattr(value, "x") and hasattr(value, "y"):
        return {"x": value.x, "y": value.y}

    # If the point is a tuple or list (e.g., (x, y))
    if isinstance(value, (tuple, list)):
        if len(value) >= 2:
            return {"x": value[0], "y": value[1]}
        elif len(value) == 1:
            return {"x": value[0]}
        else:
            return {}

    # Fallback: try to use the object's __dict__ if available
    if hasattr(value, "__dict__"):
        return value.__dict__

    # If all else fails, return the value itself
    return value<|return|>

