    result = {}
    # Class-level attributes (including properties)
    for name, value in vars(self.__class__).items():
        if name.startswith('_'):
            continue
        if callable(value):
            continue
        if isinstance(value, property):
            desc = value.__doc__ or ''
        else:
            desc = getattr(value, '__doc__', '') or ''
        result[name] = desc
    # Instance-level attributes, if requested
    if all:
        for name, value in vars(self).items():
