def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Avoid treating strings or bytes as sequences of objects
    if isinstance(seq, (str, bytes)):
        return False

    # Direct instance of FillRequest is acceptable
    if isinstance(seq, FillRequest):
        return True

    # A Source instance (or a sequence containing a Source) is not acceptable
    if isinstance(seq, Source):
        return False

    # Try to iterate over seq; if not iterable, return False
    try:
        iterator = iter(seq)
    except TypeError:
        return False

    has_fill = False
    for item in iterator:
        if isinstance(item, FillRequest):
            has_fill = True
        if isinstance(item, Source):
            # If any element is a Source, reject the whole sequence
            return False

    return has_fill<|return|>

