def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Default schema that will be used for resources without a custom observer schema.
    _DEFAULT_SCHEMA = {"metadata": {"name": {"type": "string"}}}

    # Prepare the result dictionary.
    default_schemas = {}

    # Safely access the manifest list.
    manifest = getattr(app, "spec", None)
    if manifest is None:
        return default_schemas
    manifest = getattr(manifest, "manifest", None)
    if not isinstance(manifest, list):
        return default_schemas

    for resource in manifest:
        # Skip non-dict resources.
        if not isinstance(resource, dict):
            continue

        # If the resource already has a custom observer schema, skip it.
        if resource.get("observer_schema"):
            continue

        # Use the resource name as the key for the default schema.
        name = resource.get("metadata", {}).get("name")
        if not name:
            continue

        # Assign a fresh copy of the default schema to avoid accidental mutation.
        default_schemas[name] = {
            "metadata": {"name": {"type": "string"}}
        }

    return default_schemas<|return|>

