def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")

    # Determine the spec version to use
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if type_val in ("1.0", "2.0"):
            spec_version = type_val

    # Define required keys for each supported spec version
    if spec_version == "1.0":
        required_keys = ["name", "items"]
    elif spec_version == "2.0":
        required_keys = ["name", "items", "metadata"]
    else:
        raise ValueError(f"Unsupported spec version: {spec_version}")

    # Check for missing required keys
    missing = [k for k in required_keys if k not in inventory]
    if missing:
        raise ValueError(
            f"Missing required keys for spec {spec_version}: {missing}"
        )

    # Additional simple validation: ensure 'items' is a list
    if "items" in inventory and not isinstance(inventory["items"], list):
        raise ValueError("'items' must be a list")

    # If spec_version 2.0, ensure 'metadata' is a dict
    if spec_version == "2.0" and "metadata" in inventory and not isinstance(inventory["metadata"], dict):
        raise ValueError("'metadata' must be a dictionary")

    return True<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure manifest_files is a mapping of file names to digest strings
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    # Ensure digests_used is an iterable of digest strings
    try:
        digests_used_set = set(digests_used)
    except TypeError:
        raise TypeError("digests_used must be an iterable of digest strings")

    # Collect all digests present in the manifest
    manifest_digests = set(manifest_files.values())

    # Check that every digest that is used is present in the manifest
    missing_in_manifest = digests_used_set - manifest_digests
    if missing_in_manifest:
        raise ValueError(
            f"Digests used but missing from manifest: {sorted(missing_in_manifest)}"
        )

    # Check that every digest in the manifest is actually used
    unused_in_manifest = manifest_digests - digests_used_set
    if unused_in_manifest:
        raise ValueError(
            f"Digests present in manifest but not used: {sorted(unused_in_manifest)}"
        )
    # If we reach here, all needed digests are present and used
    return None<|return|>

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type of validator
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same validator class")

    # Basic sanity checks on the version numbers
    if getattr(prior, "version", None) is None or getattr(self, "version", None) is None:
        raise ValueError("Both current and prior inventories must have a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError(
            f"Prior version ({prior.version}) must be less than current version ({self.version})"
        )

    # Ensure inventory structures exist
    if getattr(prior, "inventory", None) is None or getattr(self, "inventory", None) is None:
        raise ValueError("Both current and prior inventories must have an 'inventory' attribute")

    # Validate that every item in the prior inventory exists in the current inventory
    # and that the current inventory has at least the same quantity for each item.
    for item, qty in prior.inventory.items():
        if item not in self.inventory:
            raise ValueError(f"Item '{item}' present in prior inventory is missing from current inventory")
        if self.inventory[item] < qty:
            raise ValueError(
                f"Quantity of item '{item}' in current inventory ({self.inventory[item]}) "
                f"is less than quantity in prior inventory ({qty})"
            )

    # If all checks pass, return True to indicate success
    return True<|return|>

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Determine where the version data lives in the inventory.
    # Common patterns:
    #   1. inventory = {"versions": [ {"version": "v1", "state": {...}}, ... ]}
    #   2. inventory = {"v1": {"state": {...}}, "v2": {"state": {...}}}
    #   3. inventory = {"v1": {...}, "v2": {...}}  (state directly)
    #   4. inventory = {"versions": {"v1": {...}, "v2": {...}}}
    # We'll try to handle these cases.

    # Helper to extract state from a version entry
    def _extract_state(entry):
        if isinstance(entry, dict):
            # Prefer explicit 'state' key
            if "state" in entry:
                return entry["state"]
            # If the dict itself looks like a state mapping (keys are logical paths)
            # we return it directly
            return entry
        # If entry is not a dict, we cannot interpret it
        return None

    # Find the version entry
    version_entry = None

    # Case 1: inventory has a 'versions' key
    if isinstance(inventory, dict) and "versions" in inventory:
        vers = inventory["versions"]
        # vers could be a list or a dict
        if isinstance(vers, list):
            for v in vers:
                if isinstance(v, dict) and v.get("version") == version:
                    version_entry = v
                    break
        elif isinstance(vers, dict):
            if version in vers:
                version_entry = vers[version]
    else:
        # inventory itself might be a dict keyed by version
        if isinstance(inventory, dict) and version in inventory:
            version_entry = inventory[version]

    # If we still haven't found it, return empty dict
    if version_entry is None:
        return {}

    # Extract the state mapping
    state = _extract_state(version_entry)
    if state is None:
        return {}

    # Build the result mapping
    result = {}
    for logical_path, content in state.items():
        if isinstance(content, (list, set, tuple)):
            result[logical_path] = set(content)
        else:
            result[logical_path] = {content}
    return result<|return|>

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Accept either a dict mapping filenames to checksums or a list of
    # dicts with 'file' and 'checksum' keys.
    if isinstance(fixity, dict):
        entries = [(fname, checksum) for fname, checksum in fixity.items()]
    elif isinstance(fixity, list):
        entries = []
        for entry in fixity:
            if not isinstance(entry, dict):
                raise ValueError("Each fixity entry must be a dict")
            fname = entry.get("file")
            checksum = entry.get("checksum")
            entries.append((fname, checksum))
    else:
        raise ValueError("Fixity block must be a dict or a list of dicts")

    # Ensure that every referenced file is present in the manifest
    for fname, checksum in entries:
        if fname is None:
            raise ValueError("Fixity entry missing 'file' key")
        if fname not in manifest_files:
            raise ValueError(f"Fixity references unknown file '{fname}'")
        if not isinstance(checksum, str):
            raise ValueError(f"Checksum for '{fname}' must be a string")

    return True<|return|>

