def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    # Dictionary to hold the grouped file paths
    grouped = {}

    # First, collect all basenames that have an XML file
    xml_basenames = set()
    try:
        entries = os.listdir(folder)
    except FileNotFoundError:
        return {}

    for entry in entries:
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue
        if entry.lower().endswith('.xml'):
            basename = os.path.splitext(entry)[0]
            xml_basenames.add(basename)

    # Now group all files that share those basenames
    for entry in entries:
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue
        basename = os.path.splitext(entry)[0]
        if basename in xml_basenames:
            grouped.setdefault(basename, []).append(full_path)

    # Sort the file lists for consistency
    for key in grouped:
        grouped[key].sort()

    return grouped<|return|>

