def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _pretty(obj, level):
        # Avoid infinite recursion
        if id(obj) in visited:
            return '...'
        visited.add(id(obj))

        prefix = ' ' * (level * 4)

        # Helper to add type info if debug is True
        def add_type_info(val, val_repr):
            if debug:
                return f"{val_repr} ({type(val).__name__})"
            return val_repr

        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                k_repr = add_type_info(k, repr(k))
                v_repr = _pretty(v, level + 1)
                items.append(f"{prefix}    {k_repr}: {v_repr}")
            return '{\n' + ',\n'.join(items) + f'\n{prefix}}}'

        elif isinstance(obj, (list, tuple, set)):
            open_sym = '[' if isinstance(obj, list) else '(' if isinstance(obj, tuple) else '{'
            close_sym = ']' if isinstance(obj, list) else ')' if isinstance(obj, tuple) else '}'
            items = [f"{prefix}    {_pretty(v, level + 1)}" for v in obj]
            return f"{open_sym}\n" + ',\n'.join(items) + f"\n{prefix}{close_sym}"

        elif isinstance(obj, str):
            return add_type_info(obj, repr(obj))

        elif isinstance(obj, (int, float, bool, type(None))):
            return add_type_info(obj, repr(obj))

        else:
            # Custom object: try to pretty print its __dict__
            attrs = getattr(obj, "__dict__", None)
            if attrs is not None:
                items = []
                for k, v in attrs.items():
                    k_repr = add_type_info(k, k)
                    v_repr = _pretty(v, level + 1)
                    items.append(f"{prefix}    {k_repr}={v_repr}")
                return f"{obj.__class__.__name__}(\n" + ',\n'.join(items) + f"\n{prefix})"
            else:
                return add_type_info(obj, repr(obj))

    return _pretty(self, indent)<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        if sys.version_info[0] < 3:
            try:
                unicode_type = unicode
            except NameError:
                unicode_type = str
            if isinstance(result, unicode_type):
                return result.encode('utf-8')
        return result
    return wrapper<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to read a VERSION file in the current directory
    try:
        with open('VERSION', 'r', encoding='utf-8') as f:
            version = f.read().strip()
        return {
            'version': version,
            'full-revisionid': None,
            'dirty': False,
