def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : Iterable[Union[int, str]]
        The individual components of a version, e.g. [1, 2, 3, 'rc1'].
    style : str
        The desired rendering style. Supported styles:
        - 'semver': major.minor.patch (first three numeric pieces).
        - 'pep440': full dotted representation, preserving non-numeric parts.
        - 'full': join all pieces with dots.
        - 'short': join numeric pieces until a non-numeric piece is encountered.
        - 'none': return an empty string.

    Returns
    -------
    str
        The rendered version string.
    """
    # Normalise pieces to a list
    try:
        pieces_list = list(pieces)
    except TypeError:
        # If pieces is not iterable, treat it as a single component
        pieces_list = [pieces]

    # Normalise style to lowercase for comparison
    style = (style or "").lower()

    # Helper to determine if a piece is numeric
    def is_numeric(p):
        if isinstance(p, int):
            return True
        if isinstance(p, str):
            return p.isdigit()
        return False

    # Helper to convert a piece to int if numeric, else keep as string
    def to_int_or_str(p):
        if isinstance(p, int):
            return p
        if isinstance(p, str) and p.isdigit():
            return int(p)
        return str(p)

    if style == "none":
        return ""

    if style == "semver":
        numeric_parts = []
        for p in pieces_list:
            if is_numeric(p):
                numeric_parts.append(int(p))
                if len(numeric_parts) == 3:
                    break
        # Pad with zeros if needed
        while len(numeric_parts) < 3:
            numeric_parts.append(0)
        return ".".join(str(n) for n in numeric_parts)

    if style in ("pep440", "full"):
        # Convert all pieces to string and join with dots
        return ".".join(str(p) for p in pieces_list)

    if style == "short":
        short_parts = []
        for p in pieces_list:
            if is_numeric(p):
                short_parts.append(str(int(p)))
            else:
                break
        return ".".join(short_parts)

    # Default fallback: treat as full
    return ".".join(str(p) for p in pieces_list)<|return|>

