def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Determine the collection of objects to validate
    objects = getattr(self, 'objects', None)
    if objects is None:
        objects = getattr(self, 'storage', None)
    if objects is None:
        # No objects to validate
        return 0, 0

    # If the collection is a mapping, use its values
    if isinstance(objects, dict):
        objects = objects.values()

    num_objects = 0
    good_objects = 0

    for obj in objects:
        if obj is None:
            continue
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                validate_method = getattr(obj, 'validate', None)
                if callable(validate_method):
                    validate_method()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Validation failed for {obj!r}: {exc}")

        # Check the object's digest if requested
        if is_valid and check_digests:
            try:
                digest_method = getattr(obj, 'check_digest', None)
                if callable(digest_method):
                    digest_method()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects<|return|>

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a place to store differences
    self.different_digests = {}
    # Iterate over each version directory in order
    for version_dir in version_dirs:
        # Build the path to the inventory file for this version
        inv_path = os.path.join(self.base_path, version_dir, "inventory.json")
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Missing inventory for version '{version_dir}' at {inv_path}")
        # Load the inventory JSON
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory for version '{version_dir}': {exc}") from exc
        # Validate that every file in the root inventory is present in this version's inventory
        for rel_path, root_digest in self.root_inventory.items():
            version_digest = inv.get(rel_path)
            if version_digest is None:
                raise ValueError(f"File '{rel_path}' missing from inventory of version '{version_dir}'")
            # Record any digest differences
            if version_digest != root_digest:
                self.different_digests.setdefault(rel_path, {})[version_dir] = {
                    "root": root_digest,
                    "version": version_digest,
                }
    # If we reach here, all inventories are present and consistent
    return True<|return|>

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, value) tuples, deep‑merging MappingNode values for duplicate keys.
    """
    def merge_mapping_nodes(a, b):
        """
        Deep merge two MappingNode objects (a and b) and return a new MappingNode.
        """
        # a and b are MappingNode instances
        merged = []
        key_index = {}
        # add entries from a
        for key_node, val_node in a.value:
            key = key_node.value
            key_index[key] = len(merged)
            merged.append((key_node, val_node))
        # merge entries from b
        for key_node, val_node in b.value:
            key = key_node.value
            if key in key_index:
                idx = key_index[key]
                existing_key_node, existing_val_node = merged[idx]
                if isinstance(val_node, type(a)) and isinstance(existing_val_node, type(a)):
                    merged_val = merge_mapping_nodes(existing_val_node, val_node)
                    merged[idx] = (existing_key_node, merged_val)
                else:
                    merged[idx] = (existing_key_node, val_node)
            else:
                key_index[key] = len(merged)
                merged.append((key_node, val_node))
        return type(a)(tag=a.tag, value=merged)

    result = []
    key_index = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_index:
            idx = key_index[key]
            existing_key_node, existing_val_node = result[idx]
            if isinstance(val_node, type(existing_val_node)) and isinstance(existing_val_node, type(val_node)):
                merged_val = merge_mapping_nodes(existing_val_node, val_node)
                result[idx] = (existing_key_node, merged_val)
            else:
                result[idx] = (existing_key_node, val_node)
        else:
            key_index[key] = len(result)
            result.append((key_node, val_node))
    return result<|return|>

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not isinstance(size, str):
        raise TypeError("size must be a string")
    s = size.strip()
    if not s:
        raise ValueError("size string is empty")
    # Define multipliers
    multipliers = {
        'K': 1000,
        'M': 1000**2,
        'G': 1000**3,
        'T': 1000**4,
        'P': 1000**5,
        'E': 1000**6,
    }
    # Handle optional trailing 'B' (e.g., 'KB', 'MB')
    if s[-1].upper() == 'B':
        s = s[:-1]
    if not s:
        raise ValueError("size string has no numeric part")
    # Determine if last character is a letter indicating unit
    if s[-1].isalpha():
        unit = s[-1].upper()
        num_part = s[:-1]
        if unit not in multipliers:
            raise ValueError(f"unknown unit '{unit}' in size string")
        try:
            num = float(num_part)
        except ValueError:
            raise ValueError(f"invalid numeric part '{num_part}' in size string")
        return int(round(num * multipliers[unit]))
    else:
        # No unit, just a number
        try:
            return int(float(s))
        except ValueError:
            raise ValueError(f"invalid size string '{size}'")
<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result<|return|>

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url_args, dict):
        return url
    for key, value in url_args.items():
        placeholder_braces = f"{{{key}}}"
        placeholder_colon = f":{key}"
        url = url.replace(placeholder_braces, str(value))
        url = url.replace(placeholder_colon, str(value))
    return url<|return|>

