def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("number must be non-negative")
    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two symbols")
    # Handle zero explicitly
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()
    # Apply padding if requested
    if padding is not None:
        if padding < 0:
            raise ValueError("padding must be non-negative or None")
        if len(digits) < padding:
            # Prepend leading zeros (alphabet[0])
            digits = [alphabet[0]] * (padding - len(digits)) + digits
    return ''.join(digits)<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    # If the key to replace exists in the top-level dictionary, replace it
    if register_value in flow_params:
        flow_params[register_number] = flow_params.pop(register_value)

    # If the dictionary contains nested dictionaries, replace recursively
    for key, value in flow_params.items():
        if isinstance(value, dict):
            if register_value in value:
                value[register_number] = value.pop(register_value)
        elif isinstance(value, list):
            # Handle lists that may contain dictionaries
            for item in value:
                if isinstance(item, dict) and register_value in item:
                    item[register_number] = item.pop(register_value)

    return flow_params
<|return|>

