def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve the host to all possible addresses
        for res in socket.getaddrinfo(host, None):
            ip = res[4][0]
            # IPv4 loopback
            if ip == "127.0.0.1" or ip.startswith("127."):
                return True
            # IPv6 loopback
            if ip == "::1" or ip.startswith("::ffff:127."):
                return True
    except socket.gaierror:
        # If the host cannot be resolved, it cannot be localhost
        return False
    return False<|return|>

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine name and default from various possible matcher formats
    name = None
    default = None

    # Regex match object
    if hasattr(matcher, "group"):
        try:
            name = matcher.group(1)
            # group(2) may not exist or be None
            default = matcher.group(2) if matcher.lastindex and matcher.lastindex >= 2 else None
        except Exception:
            pass

    # Tuple or list
    if name is None and isinstance(matcher, (tuple, list)):
        if len(matcher) >= 1:
            name = matcher[0]
        if len(matcher) >= 2:
            default = matcher[1]

    # Dictionary
    if name is None and isinstance(matcher, dict):
        name = matcher.get("name")
        default = matcher.get("default")

    # If still no name, raise error
    if not name:
        raise ValueError("Matcher does not contain a variable name")

    # Fetch from environment
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise KeyError(f"Environment variable '{name}' is not set and no default provided")
    return value<|return|>

