def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import re
    import logging

    def _resolve_env(value):
        if isinstance(value, str):
            # Replace ${VAR} with environment variable
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                return os.getenv(match.group(1), '')
            return pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        else:
            return value

    config_dict = {}
    error_records = []
    logger_name = 'config_loader'
    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                data = json.load(f)
            if resolve_env:
                data = _resolve_env(data)
            if overrides:
                # Merge overrides into data (shallow)
                data.update(overrides)
            config_dict[filename] = data
        except Exception as exc:
            # Create a LogRecord for the error
            record = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to load configuration '{filename}': {exc}",
                args=(),
                exc_info=exc
            )
            error_records.append(record)
    return config_dict, error_records<|return|>

