def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    If *tentative* is False, a :class:`TypeError` is raised when the
    candidate does not satisfy the interface.  When *tentative* is True
    the function simply returns ``False`` in that case.
    """
    import inspect

    # Resolve the candidate class
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Quick check: if candidate is already a subclass of the interface
    try:
        if issubclass(candidate_cls, iface):
            return True
    except TypeError:
        # iface might not be a class; fall back to attribute checks
        pass

    # Determine the set of required attributes from the interface.
    # Prefer the ``__abstractmethods__`` attribute if present (ABC).
    iface_methods = set()
    if hasattr(iface, "__abstractmethods__"):
        iface_methods.update(iface.__abstractmethods__)
    else:
        # Fallback: consider all public callables that are not dunder
        for name, value in inspect.getmembers(iface):
            if name.startswith("_"):
                continue
            if callable(value):
                iface_methods.add(name)

    # Check that each required attribute is present and callable in the candidate.
    missing = []
    for name in iface_methods:
        if not hasattr(candidate_cls, name):
            missing.append(name)
            continue
        attr = getattr(candidate_cls, name)
        # For descriptors (e.g., @property), ``callable`` may be False.
        # We accept any attribute that is not a descriptor or is callable.
        if not (callable(attr) or isinstance(attr, property)):
            missing.append(name)

    if missing:
        msg = f"Candidate {candidate_cls.__name__} does not implement {iface.__name__} methods: {', '.join(sorted(missing))}"
        if tentative:
            return False
        raise TypeError(msg)

    return True<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key, value = next(reversed(self.items()))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    del self[key]
    return key, value<|return|>

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Helper to check a dictionary for a Diaspora payload
    def _has_diaspora_payload(data):
        if not isinstance(data, dict):
            return False
        # Common indicator: a top‑level 'diaspora' key
        if 'diaspora' in data:
            return True
        # Some payloads nest the indicator under 'payload' or 'data'
        for key in ('payload', 'data'):
            if key in data and isinstance(data[key], dict) and 'diaspora' in data[key]:
                return True
        return False

    # If the request is a mapping (e.g., dict)
    if isinstance(request, dict):
        # 1. Check public message
        if 'public' in request and _has_diaspora_payload(request['public']):
            return True
        # 2. Check private message
        if 'private' in request and _has_diaspora_payload(request['private']):
            return True
        # 3. Check legacy payload
        if 'legacy' in request and _has_diaspora_payload(request['legacy']):
            return True
        # 4. Fallback: check the request itself
        if _has_diaspora_payload(request):
            return True

    # If the request is an object with attributes
    for attr in ('public', 'private', 'legacy'):
        if hasattr(request, attr):
            try:
                val = getattr(request, attr)
                if _has_diaspora_payload(val):
                    return True
            except Exception:
                # Ignore attribute access errors
                pass

    # No Diaspora indicators found
    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # If the request is a string, look for typical Matrix markers
        if isinstance(request, str):
            if "matrix.org" in request or request.startswith("m."):
                return True

        # If the request is a mapping (e.g., dict), check for common Matrix keys
        if isinstance(request, dict):
            keys = set(request.keys())
            # Common Matrix request structure
            if {"type", "content"}.issubset(keys):
                return True
            if "msgtype" in keys:
                return True
            if "room_id" in keys or "event_id" in keys:
                return True
            if "type" in keys and isinstance(request["type"], str) and request["type"].startswith("m."):
                return True

        # For arbitrary objects, inspect attributes
        attrs = [attr for attr in dir(request) if not attr.startswith("_")]
        if "type" in attrs and hasattr(request, "content"):
            return True
        if hasattr(request, "msgtype"):
            return True
        if hasattr(request, "room_id") or hasattr(request, "event_id"):
            return True
        if hasattr(request, "type") and isinstance(getattr(request, "type"), str) and getattr(request, "type").startswith("m."):
            return True

    except Exception:
        # If any error occurs during inspection, fall back to False
        pass

    return False<|return|>

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    # Pattern for tags: words starting with '#'
    tag_pattern = re.compile(r'#\w+')
    # Pattern for fenced code blocks (```) with optional language spec
    code_block_pattern = re.compile(r'```.*?```', re.DOTALL)
    # Find all code block ranges
    code_ranges = [(m.start(), m.end()) for m in code_block_pattern.finditer(text)]

    def in_code_block(pos: int) -> bool:
        """Return True if the position is inside any code block."""
        for start, end in code_ranges:
            if start <= pos < end:
                return True
        return False

    tags: Set[str] = set()

    if replacer is None:
        # Just collect tags
        for m in tag_pattern.finditer(text):
            if not in_code_block(m.start()):
                tags.add(m.group())
        return tags, text

    # Replacement mode
    def replace_match(m: re.Match) -> str:
        if in_code_block(m.start()):
            # Leave tag unchanged inside code blocks
            return m.group()
        tags.add(m.group())
        return replacer(m.group())

    new_text = tag_pattern.sub(replace_match, text)
    return tags, new_text<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        key = child.tag
        if key in result:
            # If we already have a value for this key, convert to a list
            if isinstance(result[key], list):
                result[key].append(child)
            else:
                result[key] = [result[key], child]
        else:
            result[key] = child
    return result<|return|>

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle != entity_handle:
        raise ValueError(
            f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'"
        )<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default NodeInfo document path if not provided
    if document_path is None:
        document_path = "/nodeinfo/2.0"

    # Ensure the document path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path

    # Remove any trailing slash from the base URL to avoid double slashes
    if url.endswith("/"):
        url = url[:-1]

    # Construct the full href
    href = url + document_path

    # Return the well-known document structure
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": href
            }
        ]
    }<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json

    # Ensure handle is in the form local@domain
    if '@' not in handle:
        return {}

    local, domain = handle.split('@', 1)
    resource = f"acct:{handle}"
    query = urllib.parse.urlencode({"resource": resource})
    url = f"https://{domain}/.well-known/webfinger?{query}"

    req = urllib.request.Request(url, headers={"User-Agent": "DiasporaWebfingerClient/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            if resp.status != 200:
                return {}
            data = resp.read().decode('utf-8')
            return json.loads(data)
    except Exception:
        return {}<|return|>

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not isinstance(host, str) or not host:
        raise ValueError("host must be a non-empty string")

    # Ensure the host has a scheme
    if not host.startswith(("http://", "https://")):
        host = "https://" + host

    # Build the well-known host-meta URL
    url = host.rstrip("/") + "/.well-known/host-meta"

    import urllib.request
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise Exception(f"HTTP {resp.status} error retrieving host-meta from {url}")
            data = resp.read()
    except Exception as e:
        raise Exception(f"Error retrieving host-meta from {url}: {e}") from e

    try:
        xml = data.decode("utf-8")
    except Exception as e:
        raise Exception(f"Error decoding host-meta response: {e}") from e

    try:
        return XRD(xml)
    except Exception as e:
        raise Exception(f"Error parsing host-meta XML: {e}") from e<|return|>

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        import requests
    except Exception as e:
        return (None, e)

    try:
        req_method = getattr(requests, method.lower())
    except AttributeError:
        return (None, ValueError(f"Unsupported method: {method}"))

    try:
        response = req_method(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)<|return|>

