        missing = [field for field in required_fields if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in '{yaml_file}': {', '.join(missing)}")

        return data<|return|>

def get_spec_defaults(self):
    """
    Resolve arguments' values from spec and other sources.

    This method inspects the instance's ``spec`` attribute (which can be a
    dictionary or a list of dictionaries) and returns a dictionary of
    default values for any arguments that are not already present in
    ``self.args``.  The logic is intentionally conservative: it only
    pulls values that are explicitly marked as defaults in the spec.

    Returns
    -------
    dict
        A mapping of argument names to their default values.
    """
    # Grab the spec and the already supplied arguments
    spec = getattr(self, "spec", {})
    supplied = getattr(self, "args", {})

    defaults = {}

    # Helper to process a single spec entry
    def _process_entry(name, entry):
        # If the entry is a dict, look for a 'default' key
        if isinstance(entry, dict):
            if "default" in entry:
                defaults[name] = entry["default"]
        else:
            # If the entry itself is a value, treat it as a default
            defaults[name] = entry

    # Handle spec being a dict of name -> definition
    if isinstance(spec, dict):
        for key, value in spec.items():
            if key not in supplied:
                _process_entry(key, value)

    # Handle spec being a list of spec definitions
    elif isinstance(spec, list):
        for item in spec:
            # Each item might be a dict with a 'name' key
            if isinstance(item, dict):
                name = item.get("name")
                if name and name not in supplied:
                    _process_entry(name, item)
            # Or it might be a tuple/list like (name, definition)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                name, definition = item
                if name not in supplied:
                    _process_entry(name, definition)

    return defaults<|return|>

