def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    # Retrieve the command specification
    cmd_spec = self.commands.get(command_name)
    if cmd_spec is None:
        raise KeyError(f"Command '{command_name}' not found.")
    # Determine where options are stored
    if isinstance(cmd_spec, dict):
        options = cmd_spec.get("options")
    else:
        options = getattr(cmd_spec, "options", None)
    if options is None:
        raise KeyError(f"Command '{command_name}' has no options.")
    # Retrieve the option specification
    opt_spec = options.get(argument_name)
    if opt_spec is None:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'.")
    return opt_spec<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Accept either a dict or an iterable of (key, value) pairs
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        items = args
    else:
        # Unsupported type; return empty list
        return []

    # Return keys whose value is None or an empty string
    silent = []
    for key, value in items:
        if value is None or value == '':
            silent.append(key)
    return silent<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")
    required = getattr(self, "required_args", [])
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")
    return True<|return|>

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # If the class defines a mapping of argument names to allowed choices,
        # validate each provided argument against its allowed set.
        # The mapping may be stored in `self._choices` or `self._arg_definitions`.
        # We support both patterns for robustness.
        if hasattr(self, "_choices") and isinstance(self._choices, dict):
            choices_map = self._choices
        elif hasattr(self, "_arg_definitions") and isinstance(self._arg_definitions, dict):
            # Extract choices from each argument definition if present.
            choices_map = {
                name: getattr(defn, "choices", None)
                for name, defn in self._arg_definitions.items()
                if getattr(defn, "choices", None) is not None
            }
        else:
            # No choices information available; nothing to validate.
            return

        for name, value in args.items():
            allowed = choices_map.get(name)
            if allowed is None:
                continue  # No choices defined for this argument.
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value!r}. "
                    f"Expected one of {allowed!r}."
                )<|return|>

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not extra_vars:
            return vars_dict

        # If a dict is provided, merge directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Normalize to a list of items
        if isinstance(extra_vars, str):
            items = [extra_vars]
        else:
            items = list(extra_vars)

        for item in items:
            if isinstance(item, str) and '=' in item:
                key, value = item.split('=', 1)
                vars_dict[key] = value
            elif isinstance(item, dict):
                vars_dict.update(item)
            # ignore other types

        return vars_dict<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except Exception:
        yaml = None

    # Determine possible spec file names
    spec_filenames = [
        "plugin.yaml", "plugin.yml", "plugin.json",
        "spec.yaml", "spec.yml", "spec.json",
    ]

    spec_path = None
    for name in spec_filenames:
        candidate = os.path.join(plugin_dir, name)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if not spec_path:
        return {}

    # Load the spec file
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith((".yaml", ".yml")) and yaml:
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception:
        return {}

    if not isinstance(data, dict):
        return {}

    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                for i, item in enumerate(v):
                    if isinstance(item, dict):
                        items.update(_flatten(item, f"{new_key}{sep}{i}", sep=sep))
                    else:
                        items[f"{new_key}{sep}{i}"] = item
            else:
                items[new_key] = v
        return items

    return _flatten(data)
<|return|>

